	write("app/main.go", "package main\n", 0o644)
	write(".gitignore", "secret.env\n", 0o644)
	gitIn(t, dir, "add", ".")
	gitIn(t, dir, "commit", "--quiet", "-m", "init")

	write("README.md", "edited but not committed\n", 0o644)
	write("secret.env", "TOKEN=1\n", 0o644)
