// Package jobsview is the `:jobs` screen: what is running, and what has run
// this session.
//
// It owns no work and starts none. Every row comes from the snapshot the router
// broadcasts (jobs.ChangedMsg), which is what lets this view exist at all — a
// screen that had to ask each view what it was doing would be the fifth
// bookkeeping internal/jobs removed.
package jobsview

import (
	"strconv"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// level is which of the two tables is on screen (D2).
//
// A level rather than a tab: the second table is *about* a row of the first, so
// it is reached with → and left with ← or esc, the way every drill-down in the
// application is (Rule 111). Tabs would say the two are siblings.
type level int

const (
	levelRuns level = iota
	levelItems
)

// runRow and itemRow carry the spinner frame onto the row.
//
// The frame changes ten times a second and the columns are built once, in New,
// closing over nothing — so a Cell cannot reach the model to ask for it. Putting
// it on the row is what oci_resources does with imageRow, and for the same
// reason.
//
// It is the router's frame (D5): the one chain, taken bare from jobs.ChangedMsg
// because a table cell is measured before it is styled (Rule 122). Using
// datatable's own AdvanceSpinner here would be a second chain beside it.
type runRow struct {
	Run   jobs.Run
	Frame string
}

type itemRow struct {
	Item  jobs.Item
	Frame string
}

// Model is the jobs view.
type Model struct {
	// runs is the snapshot, every context included. contextName is what the
	// tables filter it by: a run is kept for the session and stamped, so a
	// context switch hides its runs rather than dropping them (D8).
	runs        []jobs.Run
	contextName string

	// frame is the router's bare spinner frame.
	frame string

	level   level
	openRun jobs.JobID

	runTable  datatable.Model[runRow]
	itemTable datatable.Model[itemRow]

	footer sharedcomponents.FooterMessage

	width, height int
}

// Column indexes of the runs table.
//
// Only runColumnStarted is referred to — it is what the table opens sorted by —
// and the rest of the block is what makes it right: written as `= 5` it would
// go on compiling, and start naming another column, the day one is inserted
// above it. That is the failure the containers table records in the note above
// columnPorts.
const (
	runColumnState = iota
	runColumnKind
	runColumnLabel
	runColumnProgress
	runColumnStateText
	runColumnStarted
)

// New builds the view. The context comes from the router.
//
// It is passed rather than read back from the configuration, for D68's reason
// one screen over: the router is what knows which context is current, and a
// view reading it again would be a second answer to a settled question. The
// router also drops every view on a switch (reinitializeViews), so the name
// cannot go stale.
func New(_ *config.Config, contextName string) Model {
	return Model{
		contextName: contextName,
		runTable: datatable.New(datatable.Config[runRow]{
			Columns: runColumns(),
			// Newest first. A jobs list is read to find out what is happening
			// now, and ascending would pin the session's first run to the top
			// for the rest of the session.
			SortColumn: runColumnStarted,
			SortDesc:   true,
		}),
		itemTable: datatable.New(datatable.Config[itemRow]{
			Columns: itemColumns(),
			// The order the batch was dispatched in. It is the only order that
			// means anything here — the targets of a run have no natural rank,
			// and sorting by state would move a row out from under the cursor
			// every time one settled.
			SortColumn: -1,
		}),
	}
}

// runColumns describes the runs table.
//
// The first column is the run's **state**, not its kind, and it is also where
// the spinner goes. That is the containers table's shape and it is deliberate:
// a jobs list is scanned to find the one that failed and the one still going,
// so the glyph answers the question the reader arrived with, and the Kind
// column says in a word what sort of work it was.
//
// A state glyph column colours by the semantic status styles rather than by a
// theme.IconStyle role, which is the choice the containers table already makes.
// Roles exist for icons that name an *object* — a namespace, a repository, an
// image — where a palette should be able to tell them apart. A state has a
// colour already, and five new roles would give a theme five ways to make
// "failed" not red.
//
// The glyph and the State word are not the redundancy that a glyph beside its
// own name usually is: the glyph column doubles as the spinner while the run
// goes, and the word is what separates the four settled outcomes — "cancelled"
// from "failed" above all, which is the distinction Run.cancelled exists for.
func runColumns() []datatable.Column[runRow] {
	return []datatable.Column[runRow]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r runRow) string { return runStateGlyph(r) },
			Style: func(r runRow) lipgloss.Style { return runStateStyle(r.Run.State()) },
		},
		{
			Title: "Kind", Sizing: datatable.SizingFixed, MinWidth: 8,
			Cell: func(r runRow) string { return string(r.Run.Kind) },
			Less: func(a, b runRow) bool { return a.Run.Kind < b.Run.Kind },
			// The state is searchable here rather than through its own column,
			// so `/failed` and `/scan` both work while the glyph column stays
			// out of the filter (Rule 125).
			Search: func(r runRow) string { return string(r.Run.Kind) + " " + string(r.Run.State()) },
		},
		{
			Title: "Label", Sizing: datatable.SizingContent,
			MinWidth: 14, MaxWidth: 40, Flex: 2, TruncateHead: true,
			Cell:   func(r runRow) string { return r.Run.Label },
			Less:   func(a, b runRow) bool { return strings.ToLower(a.Run.Label) < strings.ToLower(b.Run.Label) },
			Search: func(r runRow) string { return r.Run.Label },
		},
		{
			Title: "Progress", Sizing: datatable.SizingFixed, MinWidth: 9,
			Cell: func(r runRow) string { return progressCell(r.Run) },
			// By how far along, not by how many: 1/2 is further than 3/12, and
			// comparing the numerators would rank the bigger batch higher for
			// having more left to do.
			Less: func(a, b runRow) bool { return fraction(a.Run) < fraction(b.Run) },
		},
		{
			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:  func(r runRow) string { return string(r.Run.State()) },
			Style: func(r runRow) lipgloss.Style { return runStateStyle(r.Run.State()) },
			Less:  func(a, b runRow) bool { return a.Run.State() < b.Run.State() },
		},
		{
			Title: "Started", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 12,
			Cell: func(r runRow) string { return theme.TimeAgo(r.Run.StartedAt) },
			Less: func(a, b runRow) bool { return a.Run.StartedAt.Before(b.Run.StartedAt) },
		},
	}
}

// itemColumns describes one run's targets.
//
// No Started column: an item has no timestamp of its own, and every target of a
// batch shares the run's. What an item has that a run does not is Detail — the
// reason a sync was skipped, the fact a scan failed — and that is what the
// width is worth spending on here.
func itemColumns() []datatable.Column[itemRow] {
	return []datatable.Column[itemRow]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r itemRow) string { return itemStateGlyph(r) },
			Style: func(r itemRow) lipgloss.Style { return itemStateStyle(r.Item.State) },
		},
		{
			Title: "Target", Sizing: datatable.SizingContent,
			MinWidth: 20, MaxWidth: 60, Flex: 3, TruncateHead: true,
			Cell:   func(r itemRow) string { return r.Item.Name() },
			Search: func(r itemRow) string { return r.Item.Name() },
		},
		{
			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:   func(r itemRow) string { return string(r.Item.State) },
			Style:  func(r itemRow) lipgloss.Style { return itemStateStyle(r.Item.State) },
			Search: func(r itemRow) string { return string(r.Item.State) },
		},
		{
			Title: "Detail", Sizing: datatable.SizingContent, MinWidth: 10, Flex: 2,
			Cell:   func(r itemRow) string { return dashIfEmpty(r.Item.Detail) },
			Style:  func(r itemRow) lipgloss.Style { return detailStyle(r.Item) },
			Search: func(r itemRow) string { return r.Item.Detail },
		},
	}
}

// progressCell is the "7/12" of a run.
//
// A settled run keeps it. "12/12" beside "3/12" is what makes the size of a
// batch readable at a glance, and blanking it once the run is over would empty
// the column for most of the list.
func progressCell(r jobs.Run) string {
	return strconv.Itoa(r.Done()) + "/" + strconv.Itoa(r.Total())
}

// fraction is how far along a run is, in [0,1]. An empty run is finished.
func fraction(r jobs.Run) float64 {
	if r.Total() == 0 {
		return 1
	}
	return float64(r.Done()) / float64(r.Total())
}

// dashIfEmpty is the placeholder for a cell with nothing in it — a dash rather
// than a blank, so the column still reads as a column (Rule 122).
func dashIfEmpty(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

// detailStyle dims the placeholder and leaves a real detail alone.
//
// "already there" or "scan failed — check logs" is what the column exists for,
// so dimming it would grey out exactly what the reader came to read. What is
// dim is the absence, which is Rule 122's rule for a zero.
func detailStyle(i jobs.Item) lipgloss.Style {
	if i.Detail == "" {
		return theme.DimStyle
	}
	return lipgloss.NewStyle()
}
package jobsview

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// The reasons a key is refused, as named constants: the header reads them to
// grey, the handler reads them to refuse, and a test reads them to check the
// two agree (Rule 130).
const (
	reasonNoRun         = "No run selected"
	reasonNoTarget      = "No target selected"
	reasonEmptyRun      = "This run has no targets"
	reasonInsideRun     = "Already inside a run"
	reasonTopLevel      = "Already at the top level"
	reasonItemsUnsorted = "Targets keep the order they were dispatched in"
	reasonRunSettled    = "This run has already finished"
	reasonTargetSettled = "This target has already finished"
)

// stopRefusal names why a run cannot be stopped, in the run's own words.
//
// The wording is per kind because the reason is: a delete in flight must never
// be cut, and saying so with the verb the row already shows is what makes the
// greyed key readable without opening the help.
func stopRefusal(kind jobs.Kind) string {
	return "A " + string(kind) + " cannot be stopped once it has started"
}

// availability is what the selected row and the current level permit, computed
// once and read by both halves of the view.
//
// One field per key rather than a bool and a string apart: an empty reason
// means available, so the two cannot disagree.
type availability struct {
	Open  shortcut.Availability
	Close shortcut.Availability
	Sort  shortcut.Availability
	Stop  shortcut.Availability
}

// availability answers for the level, and inside it for the selected row.
//
// The list is the same three entries at both levels, and only the greying
// changes (Rule 130): a shortcut column that reorganised itself every time the
// reader pressed → would be unreadable exactly when they are moving around.
func (m Model) availability() availability {
	var a availability

	if m.level == levelItems {
		// The drill is one level deep by construction — there is nothing under
		// a target — so → has nowhere left to go, and `.` has no column to
		// cycle because the item table opens unsorted on purpose (see New).
		a.Open = shortcut.Unavailable(reasonInsideRun)
		a.Sort = shortcut.Unavailable(reasonItemsUnsorted)
		a.Stop = m.itemStoppable()
		return a
	}

	a.Close = shortcut.Unavailable(reasonTopLevel)
	switch row, ok := m.runTable.Selected(); {
	case !ok:
		a.Open = shortcut.Unavailable(reasonNoRun)
		a.Stop = shortcut.Unavailable(reasonNoRun)
	case row.Run.Total() == 0:
		// A run with no targets is a real thing: a batch launched when every
		// candidate was already busy. It settles at once, and there is nothing
		// behind it to open.
		a.Open = shortcut.Unavailable(reasonEmptyRun)
		a.Stop = m.runStoppable(row.Run)
	default:
		a.Stop = m.runStoppable(row.Run)
	}
	return a
}

// runStoppable answers for `K` on a run: the queue stops whatever the kind, so
// what is left to say is whether there is anything left to stop (D7).
func (m Model) runStoppable(run jobs.Run) shortcut.Availability {
	switch {
	case run.Finished():
		return shortcut.Unavailable(reasonRunSettled)
	case !run.Stoppable():
		return shortcut.Unavailable(stopRefusal(run.Kind))
	}
	return shortcut.Availability{}
}

// itemStoppable answers for `K` on one target.
//
// Narrower than the run, and deliberately: stopping a run stops its queue, but
// cutting a single piece of work in flight is only offered where cutting leaves
// nothing behind. A half-written clone is the case that decides it.
func (m Model) itemStoppable() shortcut.Availability {
	run, ok := m.openedRun()
	if !ok {
		return shortcut.Unavailable(reasonNoRun)
	}
	row, ok := m.itemTable.Selected()
	if !ok {
		return shortcut.Unavailable(reasonNoTarget)
	}
	switch {
	case row.Item.State.Terminal():
		return shortcut.Unavailable(reasonTargetSettled)
	case !run.ItemStoppable(row.Item):
		return shortcut.Unavailable(stopRefusal(run.Kind))
	}
	return shortcut.Availability{}
}

package jobsview

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init returns nothing.
//
// The view fetches nothing and starts no chain: its rows arrive in the
// broadcast, and switchView hands it the snapshot on the way in (sendJobsTo).
// A view that asked on arrival would be reading a second answer to a question
// the router already holds.
func (m Model) Init() tea.Cmd { return nil }

// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)
		return m, nil

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)
	}

	m.footer.Handle(msg)
	return m, nil
}

// handleJobsChanged takes the router's snapshot and rebuilds both tables.
//
// Both, not just the one on screen: the item table is what the cursor stands in
// while a target settles under it, and rebuilding it only on the way in would
// freeze it at the moment it was opened.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.runs = msg.Runs
	m.frame = msg.Frame
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	m.refreshRows()
	return m, nil
}

// visibleRuns is what this view shows: the runs of the current context (D8).
// The table decides the order; this decides which exist.
func (m Model) visibleRuns() []jobs.Run {
	return jobs.FilterContext(m.runs, m.contextName)
}

// openedRun returns the run the item level is showing, and whether it is still
// in the snapshot.
//
// It can stop being: the registry keeps the last MaxFinishedRuns settled runs,
// so a run left open long enough is eventually pruned out from under the
// cursor. refreshRows is what answers for that.
func (m Model) openedRun() (jobs.Run, bool) {
	for _, run := range m.visibleRuns() {
		if run.ID == m.openRun {
			return run, true
		}
	}
	return jobs.Run{}, false
}

// refreshRows rebuilds both tables from the snapshot, and falls back to the
// list when the run being shown has been pruned.
func (m *Model) refreshRows() {
	runs := m.visibleRuns()
	rows := make([]runRow, len(runs))
	for i, run := range runs {
		rows[i] = runRow{Run: run, Frame: m.frame}
	}
	m.runTable.SetItems(rows)

	run, ok := m.openedRun()
	if m.level == levelItems && !ok {
		// Back to the list rather than an empty table: the run is gone, so
		// there is nothing to say about it, and a breadcrumb naming a label
		// that no longer exists would be worse than no breadcrumb.
		m.level = levelRuns
		m.openRun = 0
		m.itemTable.SetItems(nil)
		return
	}

	items := make([]itemRow, len(run.Items))
	for i, item := range run.Items {
		items[i] = itemRow{Item: item, Frame: m.frame}
	}
	m.itemTable.SetItems(items)
}

// handleKeyMsg routes a key. The filter comes first (Rule 136): while it has
// the keyboard, every key is text.
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.inFilter() {
		return m.forwardToTable(msg)
	}

	switch msg.String() {
	case "right":
		return m.openSelected()

	case "left", "esc":
		return m.closeItems()

	case keymap.Kill:
		return m.stopSelected()

	case ".":
		return m.cycleSort()

	case "/":
		return m.activateSearch()
	}

	return m.forwardToTable(msg)
}

// forwardToTable hands the key to whichever level is on screen.
//
// The two tables are datatable.Model over different types, so this is a branch
// rather than an interface: a common interface would have to be declared over
// FilterBar and Update in a package that owns neither, for two call sites.
func (m Model) forwardToTable(msg tea.Msg) (tea.Model, tea.Cmd) {
	if m.level == levelItems {
		return m, m.itemTable.Update(msg)
	}
	return m, m.runTable.Update(msg)
}

// stopSelected asks the router to stop what the cursor is on: the run at the
// top level, one target inside a run.
//
// It asks rather than acts, like every other write to the registry: the router
// owns it, and a view holding a pointer to it is the thing D1 keeps out. What
// the view holds is the identifier, read off the row it is rendering.
func (m Model) stopSelected() (tea.Model, tea.Cmd) {
	if stop := m.availability().Stop; !stop.Enabled() {
		return m, m.footer.Warn(stop.Reason)
	}
	if m.level == levelItems {
		row, _ := m.itemTable.Selected()
		return m, jobs.CancelItem(m.openRun, row.Item.Target)
	}
	row, _ := m.runTable.Selected()
	return m, jobs.Cancel(row.Run.ID)
}

// cycleSort moves the runs table on to its next sortable column.
//
// It is guarded rather than forwarded, so the refusal and the greying come from
// one calculation (Rule 130): the item table declares no comparator, and a `.`
// that silently did nothing there would be the `return m, nil` the rule exists
// to remove.
func (m Model) cycleSort() (tea.Model, tea.Cmd) {
	if sort := m.availability().Sort; !sort.Enabled() {
		return m, m.footer.Warn(sort.Reason)
	}
	m.runTable.CycleSort()
	return m, nil
}

func (m Model) activateSearch() (tea.Model, tea.Cmd) {
	if m.level == levelItems {
		return m, m.itemTable.FilterBar().ActivateSearch()
	}
	return m, m.runTable.FilterBar().ActivateSearch()
}

// filterBar is the bar of the level on screen. The footer renders it and
// GetFooterHeight budgets for it (Rule 136).
func (m Model) filterBar() *sharedcomponents.FilterBar {
	if m.level == levelItems {
		return m.itemTable.FilterBar()
	}
	return m.runTable.FilterBar()
}

func (m Model) inFilter() bool { return m.filterBar().InEditMode() }

// InEditMode tells the router the filter has the keyboard (app.FormView).
func (m Model) InEditMode() bool { return m.inFilter() }

// FilterBarVisible closes the viewport rectangle around the bar
// (app.FilterBarView).
func (m Model) FilterBarVisible() bool { return m.filterBar().IsVisible() }

// openSelected drills into the run under the cursor (Rule 111: → descends).
func (m Model) openSelected() (tea.Model, tea.Cmd) {
	if open := m.availability().Open; !open.Enabled() {
		return m, m.footer.Warn(open.Reason)
	}
	row, _ := m.runTable.Selected()
	m.openRun = row.Run.ID
	m.level = levelItems
	m.itemTable.GotoTop()
	m.refreshRows()
	m.resize(m.width, m.height)
	return m, nil
}

// closeItems goes back up.
//
// At the top level there is nowhere to go, and that is not a refusal worth
// naming: `esc` is what a user presses to leave a screen, this view has none
// behind it, and a footer line on every stray esc would be noise. Rule 130
// greys the entry instead, which says the same thing before the key is pressed.
func (m Model) closeItems() (tea.Model, tea.Cmd) {
	if m.level == levelRuns {
		return m, nil
	}
	m.level = levelRuns
	m.openRun = 0
	m.resize(m.width, m.height)
	return m, nil
}

// resize lays both tables out.
//
// Both, again: the item table is measured for the size it will be opened at, so
// → cannot show one frame of a table sized for a window that has since changed.
//
// The breadcrumb costs a line at the item level (Rule 123), and it is not
// subtracted here: it is rendered in the footer, so GetFooterHeight already
// asks the router for it, and taking it off the table too would take it twice.
func (m *Model) resize(width, height int) {
	m.width = width
	m.height = height

	m.runTable.Resize(width, max(height-1, 1))
	m.itemTable.Resize(width, max(height-1, 1))
}
package jobsview

import (
	"strconv"
	"strings"

	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// GetTitle names the view, and the run when one is open.
func (m Model) GetTitle() string {
	base := theme.IconHourglass + " Jobs"
	if run, ok := m.openedRun(); ok && m.level == levelItems {
		return base + " " + theme.IconChevronRight + " " + run.Label
	}
	return base
}

// GetIcon returns the view icon. The title carries it, as everywhere else.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo says how much of the session is on screen.
//
// Running first, because it is why the view is open. The total is the runs of
// this context, which is what the table holds — not the registry's, which also
// counts the ones a context switch is hiding.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	runs := m.visibleRuns()
	return []shortcut.HeaderInfo{
		{Key: "Running", Value: strconv.Itoa(len(jobs.Unfinished(runs))), Style: theme.HeaderValueStyle},
		{Key: "Runs", Value: strconv.Itoa(len(runs)), Style: theme.HeaderValueStyle},
	}
}

// GetShortcuts returns the header's shortcut column (Rules 130, 137, 138).
//
// The obvious keys are absent: ↑↓, PageUp/PageDown, Home/End. What is left is
// the drill, the sort, the filter and help — and the three that vary are greyed
// rather than dropped, so the column is the same four lines at both levels.
func (m Model) GetShortcuts() shortcut.Shortcuts {
	a := m.availability()
	return []shortcut.Shortcut{
		{Key: keymap.Kill, Description: "Stop", Disabled: !a.Stop.Enabled()},
		{Key: "→", Description: "Open targets", Disabled: !a.Open.Enabled()},
		{Key: "esc", Description: "Go back", Disabled: !a.Close.Enabled()},
		{Key: ".", Description: "Sort", Disabled: !a.Sort.Enabled()},
		{Key: "/", Description: "Filter"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
//
// The breadcrumb is a line of the footer at the item level, and the filter bar
// adds its own when visible. Both are asked for here so the router can take
// them off the viewport.
func (m Model) GetFooterHeight() int {
	height := 2 + m.filterBar().ExtraHeight()
	if m.level == levelItems {
		height++
	}
	return height
}

// RenderFooter renders the lines below the viewport (Rule 124).
//
// Order: breadcrumb, filter bar, blank, message. The breadcrumb sits directly
// under the table because it names the level the table is showing (Rule 123).
func (m Model) RenderFooter(width int) string {
	var parts []string
	if m.level == levelItems {
		parts = append(parts, m.renderBreadcrumb(width))
	}
	if bar := m.filterBar(); bar.IsVisible() {
		parts = append(parts, bar.View())
	}
	parts = append(parts, theme.EmptyLineBg(width), m.footer.View(width, m.status()))
	return strings.Join(parts, "\n")
}

// renderBreadcrumb is the trail below the table at the item level (Rule 123).
// Breadcrumb mode: it is not navigable, the level shown is highlighted and the
// one above it is dimmed.
func (m Model) renderBreadcrumb(width int) string {
	run, ok := m.openedRun()
	if !ok {
		return theme.EmptyLineBg(width)
	}
	tabs := []theme.TabItem{
		{Label: "Runs"},
		{Label: string(run.Kind) + " " + theme.IconChevronRight + " " + run.Label},
	}
	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, 1), width)
}

// status is the derived line, with no timer (Rule 128).
//
// It is the shared sentence every other footer says while work runs, and it is
// asked for with no origin: this view launched none of it, so the detailed form
// would be a lie about ownership. What it says instead is the count — which is
// also the one form that does not end in ":jobs for details", because that is
// where the reader already is.
func (m Model) status() sharedcomponents.Status {
	live := jobs.Unfinished(m.visibleRuns())
	if len(live) == 0 {
		return sharedcomponents.Status{}
	}
	return sharedcomponents.Status{
		Text:    sharedcomponents.Plural(len(live), "job", "jobs") + " running",
		Spinner: true,
	}
}

// View renders the table of the level on screen.
//
// There is no loading branch: this view fetches nothing, so it is never between
// a request and an answer. A table with nothing to show still renders its
// header and no rows (datatable.View() does this on its own) — the count that
// says why (zero runs, or a filter matching none of them) lives in the header
// (GetHeaderInfo), not in the body.
func (m Model) View() string {
	if m.level == levelItems {
		return m.itemTable.View()
	}
	return m.runTable.View()
}

