func SameHost(remoteURL, forgeURL string) bool {
	remote := HostOf(NormalizeRemoteURL(remoteURL))
	forge := HostOf(forgeURL)
	if remote == "" || forge == "" {
		return false
	}
	return strings.EqualFold(remote, forge)
}
